{
  "problem_id": "count_pairs_with_distance_k",
  "nodes": [
    {
      "id": 1,
      "type": "start",
      "label": "Start",
      "next": 2
    },
    {
      "id": 2,
      "type": "process",
      "label": "Input: coordinates (2D array), k (integer)",
      "action": "ctx['coordinates']=ctx['arg0']; ctx['k']=ctx['arg1']",
      "next": 3
    },
    {
      "id": 3,
      "type": "process",
      "label": "Initialize ans = 0, d = Counter(map(tuple, coordinates))",
      "action": "ctx['ans']=0; ctx['d']=dict(); [ctx['d'][tuple(coord)] = ctx['d'].get(tuple(coord), 0) + 1 for coord in ctx['coordinates']]",
      "next": 4
    },
    {
      "id": 4,
      "type": "process",
      "label": "Initialize R = [(i, k-i) for i in range(k+1)]",
      "action": "ctx['R']=[(i, ctx['k']-i) for i in range(ctx['k']+1)]",
      "next": 5
    },
    {
      "id": 5,
      "type": "decision",
      "label": "For each (x, y) in coordinates",
      "logic": "len(ctx['coordinates']) > 0",
      "true_next": 6,
      "false_next": 9
    },
    {
      "id": 6,
      "type": "process",
      "label": "Decrement d[(x, y)] by 1",
      "action": "ctx['d'][(ctx['coordinates'][0][0], ctx['coordinates'][0][1])] -= 1",
      "next": 7
    },
    {
      "id": 7,
      "type": "process",
      "label": "Calculate sum: sum(d[(x^i, y^j)] for i,j in R)",
      "action": "ctx['sum']=0; [ctx['sum'] += ctx['d'].get((ctx['coordinates'][0][0] ^ i, ctx['coordinates'][0][1] ^ j), 0) for i, j in ctx['R']]",
      "next": 8
    },
    {
      "id": 8,
      "type": "process",
      "label": "Update ans: ans += sum",
      "action": "ctx['ans'] += ctx['sum']; ctx['coordinates'].pop(0)",
      "next": 5
    },
    {
      "id": 9,
      "type": "end",
      "label": "Output: ans (number of pairs with distance k)",
      "output": "ctx['ans']"
    }
  ]
}
